@import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700;800&family=Space+Grotesk:wght@400;500;600;700&display=swap');
:root{--ink:#121322;--panel:#191a2b;--panel2:#202136;--line:rgba(227,222,255,.09);--muted:#85869f;--cream:#f3f0e9;--gold:#edc773;--lav:#b7a3ff;--mint:#81dbbe;--coral:#f18a8f;font-family:'DM Sans',sans-serif;color:var(--cream);background:#10111f;font-synthesis:none}*{box-sizing:border-box}body{margin:0;min-width:320px;min-height:100vh;background:radial-gradient(ellipse at 68% 32%,#1b1b31 0,#111221 55%,#10111e 100%);color:var(--cream)}button{font:inherit;color:inherit;cursor:pointer}.app-shell{max-width:1512px;margin:0 auto;padding:0 56px}.topbar{height:78px;border-bottom:1px solid var(--line);display:flex;align-items:center;justify-content:space-between}.brand{display:flex;align-items:center;gap:12px;color:#f4f0e8;text-decoration:none;font:700 15px 'Space Grotesk',sans-serif;letter-spacing:1.55px}.brand b{color:#aaa3c1;font-weight:500}.brand-mark{display:grid;place-items:center;width:29px;height:29px;border:1px solid rgba(237,199,115,.45);border-radius:9px;color:var(--gold);font-size:19px;box-shadow:0 0 16px #edc77315}.season-tag{font-size:10px;font-weight:700;letter-spacing:1.6px;color:#aaa9bf}.season-tag i{color:#54546b;font-style:normal;padding:0 8px}.season-dot,.pulse-dot,.state-orb{display:inline-block;width:6px;height:6px;background:#a990ff;border-radius:50%;box-shadow:0 0 11px #a990ff;margin-right:8px;vertical-align:1px}.player-chip{display:flex;align-items:center;gap:10px;padding:7px 10px 7px 7px;border:1px solid var(--line);border-radius:10px;background:#ffffff04}.player-avatar{width:32px;height:32px;border-radius:8px;background:linear-gradient(145deg,#d2b88a,#886e68);display:grid;place-items:center;color:#fff4d8;font-size:19px}.player-chip strong{display:block;font-size:11px;letter-spacing:.2px}.player-chip small{display:block;margin-top:3px;font-size:8px;letter-spacing:1px;color:var(--muted)}.player-chip small span{color:var(--gold)}.player-chevron{font-size:15px;color:#9998ac;margin-left:10px}.game-layout{display:grid;grid-template-columns:minmax(0,1fr) 3