ius:8px;background:#151526c9;backdrop-filter:blur(8px);box-shadow:0 5px 16px #0002}.wave-symbol{width:28px;height:28px;border-radius:7px;background:#edc77318;display:grid;place-items:center;color:var(--gold);font-size:18px}.wave-banner small{font-size:7px;letter-spacing:1.1px;color:#a5a2b7;display:block}.wave-banner strong{font:700 11px 'Space Grotesk';letter-spacing:.5px;display:block;margin-top:2px}.banner-rule{height:25px;width:1px;background:#ffffff20;margin:0 2px 0 5px}.enemy-count{font-size:9px;color:#bbb9c9}.enemy-count b{font-size:12px;color:#f2eee5}.wave-progress{position:absolute;z-index:3;top:38px;left:0;right:0;height:2px;background:#fff1}.wave-progress span{display:block;height:100%;width:0;background:var(--gold);transition:width .25s}.stage-controls{position:absolute;top:51px;right:13px;z-index:5;display:flex;gap:5px}.mini-control{width:29px;height:28px;border:1px solid #fff2;border-radius:7px;background:#141522aa;color:#e3ddcf;font-size:13px;backdrop-filter:blur(8px)}.placement-hint{position:absolute;left:50%;bottom:13px;transform:translateX(-50%);white-space:nowrap;padding:7px 12px;border:1px solid #ffffff18;border-radius:30px;background:#161729b5;color:#d4cbaf;font-size:7px;font-weight:700;letter-spacing:1.3px;backdrop-filter:blur(8px);pointer-events:none;opacity:0;transition:opacity .2s}.placement-hint.visible{opacity:1}.ability-float{position:absolute;right:15px;bottom:14px;z-index:4}.ultimate-btn{width:60px;height:60px;border:1px solid #d6c0ff70;border-radius:50%;background:radial-gradient(circle at 50% 43%,#8d70ddc9,#392f68e8 70%);box-shadow:0 0 0 4px #a58af522,0 0 22px #b49bff55;display:flex;flex-direction:column;align-items:center;justify-content:center;position:relative;transition:.2s}.ultimate-btn span{font-size:20px;line-height:20px;color:#fff2d6}.ultimate-btn small{font-size:6px;letter-spacing:.5px;color:#e7ddff}.ultimate-btn b{position:absolute;right:-3px;top:-3px;border-radius:5px;background:#e8d8ff;color:#352c4e;font-size:8px;padding:2px 4px}.ultimate-btn:hover{transform:scale(1.07);filter:brightness(1.18)}.ultimate-btn:disabled{filter:grayscale(.7);opacity:.48;cursor:default}.battle-footer{height:57px;display:flex;align-items:center;padding:0 14px;gap:14px;border-top:1px solid #ffffff0b;background:#191a2a}.wave-state{display:flex;align-items:center;min-width:184px;color:#a8a6b9;font-size:8px;letter-spacing:1.1px;font-weight:700}.state-orb{width:6px;height:6px;margin-right:8px;background:#80d2ae;box-shadow:0 0 9px #80d2ae}.wave-readout{font-size:8px;letter-spacing:1px;color:#9291a8;display:flex;align-items:baseline;gap:5px}.wave-readout strong{font:600 17px 'Space Grotesk';color:var(--cream)}.wave-readout .readout-divider{color:#69687a}.start-wave{margin-left:auto;border:0;border-radius:7px;padding:10px 14px;background:#e9c572;color:#28241e;font-size:8px;letter-spacing:1px;font-weight:800;display:flex;align-items:center;gap:14px;transition:.2s;box-shadow:0 4px 14px #edc77320}.start-wave:hover{background:#ffdb88;transform:translateY(-1px)}.start-wave b{font-size:14px}.start-wave:disabled{opacity:.5;cursor:default;transform:none}.roster-panel{margin-top:24px}.section-heading,.intel-heading{display:flex;justify-content:space-between;align-items:flex-end;margin-bottom:12px}.section-heading h2{font:600 18px 'Space Grotesk';margin:5px 0 0;letter-spacing:-.4px}.deck-count{font:500 9px 'DM Sans';letter-spacing:.5px;color:#8f8da3;margin-left:6px}.text-action{border:0;background:none;color:#b2a7d8;font-size:8px;font-weight:700;letter-spacing:1.1px;padding:5px 0}.text-action span{font-size:12px;margin-left:5px}.hero-cards{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px}.hero-card{height:101px;position:relative;overflow:hidden;border:1px solid #ffffff14;border-radius:10px;background:linear-gradient(110deg,#242439,#1b1c2b 75%);display:flex;align-items:center;padding:10px;gap:10px;text-align:left;transition:.2s}.hero-card:hover{border-color:#e4c47777;transform:translateY(-2px)}.hero-card.selected{border-color:#edc7739c;box-shadow:inset 0 0 0 1px #edc7732a,0 5px 20px #0002}.hero-card.placed{background:linear-gradient(110deg,#27263a,#1c1d2c 75%)}.hero-art{position:relative;flex:0 0 57px;width:57px;height:72px;border-radius:8px;overflow:hidden;display:grid;place-items:center;font-size:35px;isolation:isolate}.hero-art:before{content:'';position:absolute;inset:18px 3px -4px;border-radius:50% 50% 0 0;z-index:-1;background:linear-gradient(145deg,var(--hero-color),#25243a 80%);opacity:.9}.hero-art:after{content:'';position:absolute;width:24px;height:26px;top:9px;border-radius:46% 46% 40% 40%;background:linear-gradient(130deg,#ffe6c8,#b88580);box-shadow:0 0 0 4px #292134;z-index:-1}.hero-art .hair{position:absolute;top:4px;width:30px;height:21px;border-radius:50% 52% 24% 26%;background:var(--hair);z-index:1}.hero-art .eyes{position:absolute;top:21px;width:15px;height:3px;border-radius:50%;background:#67445a;z-index:2;box-shadow:8px 0 0 #67445a}.hero-art .spark{position:absolute;right:5px;top:24px;color:var(--hero-color);font-size:11px;text-shadow:0 0 7px var(--hero-color)}.hero-copy{min-width:0;align-self:center;flex:1}.hero-copy .hero-role{display:block;font-size:7px;letter-spacing:1px;color:#a7a4bd;font-weight:700;margin-bottom:5px}.hero-copy strong{display:block;font:600 12px 'Space Grotesk';white-space:nowrap}.hero-copy small{display:block;color:#a6a3b3;font-size:8px;margin-top:4px}.hero-cost{position:absolute;right:9px;top:8px;color:var(--gold);font-size:8px;font-weight:700}.hero-rank{position:absolute;right:10px;bottom:9px;color:#88869d;font-size:7px;letter-spacing:.5px}.hero-card .placed-check{display:none;position:absolute;left:7px;top:7px;width:14px;height:14px;border-radius:50%;background:var(--mint);color:#15201e;place-items:center;font-size:9px;font-weight:900}.hero-card.placed .placed-check{display:grid}.side-column{display:flex;flex-direction:column;gap:13px}.resource-panel{height:67px;display:grid;grid-template-columns:1fr 1.15fr;border:1px solid var(--line);border-radius:10px;background:#1a1b2b;padding:10px 12px}.resource-item{display:flex;align-items:center;gap:8px;position:relative}.resource-item+ .resource-item{border-left:1px solid var(--line);padding-left:12px}.resource-icon{width:28px;height:28px;border-radius:8px;display:grid;place-items:center;font-size:16px}.gold-icon{color:var(--gold);background:#edc77316}.heart-icon{color:#ed8e9c;background:#ed829616}.resource-item small{display:block;font-size:7px;letter-spacing:.7px;color:#9a98ad;font-weight:700}.resource-item strong{display:block;font:600 15px 'Space Grotesk';margin-top:2px}.resource-item strong i{font-style:normal;font-size:9px;color:#77768c}.plus-btn{margin-left:auto;border:1px solid #ffffff20;background:#fff1;color:#c5bdd7;border-radius:5px;font-size:13px;width:19px;height:19px;line-height:15px;padding:0}.vitality-bar{position:absolute;left:49px;right:1px;bottom:1px;height:2px;background:#ffffff14}.vitality-bar span{display:block;width:100%;height:100%;background:#df8998;transition:width .3s}.mission-panel{position:relative;border:1px solid #c2aafc24;border-radius:10px;background:radial-gradient(ellipse at 100% 0%,#5146754a,#252239 49%,#1d1d2e 100%);padding:16px 16px 14px;min-height:241px;overflow:hidden}.mission-panel:after{content:'✧';position:absolute;top:20px;right:19px;color:#edc77355;font-size:38px}.panel-kicker{font-size:7px;letter-spacing:1.4px;font-weight:700;color:#c4bbdd}.panel-kicker .pulse-dot{width:5px;height:5px;background:#87d8b8;margin-right:6px;box-shadow:0 0 8px #87d8b8}.mission-id{float:right;color:#817d98}.mission-panel h3{font:600 22px/1.1 'Space Grotesk';letter-spacing:-.7px;margin:15px 0 18px}.mission-progress>div:first-child{display:flex;justify-content:space-between;font-size:7px;font-weight:700;letter-spacing:.9px;color:#9a97af}.mission-progress b{color:#80d7b6;letter-spacing:1px}.threat-track{height:3px;background:#ffffff15;border-radius:3px;margin-top:7px;overflow:hidden}.threat-track i{display:block;height:100%;width:21%;background:linear-gradient(90deg,#7ec6a6,#decf7f);transition:width .3s}.mission-metrics{display:grid;grid-template-columns:repeat(3,1fr);margin:14px 0 12px;padding:11px 0;border-top:1px solid #ffffff10;border-bottom:1px solid #ffffff10}.mission-metrics div+div{padding-left:12px;border-left:1px solid #ffffff10}.mission-metrics small{font-size:6px;letter-spacing:.7px;color:#8a879e;display:block;white-space:nowrap}.mission-metrics strong{display:block;margin-top:5px;font:600 13px 'Space Grotesk'}.mission-objective{display:flex;align-items:center;gap:8px;font-size:8px;line-height:1.45;color:#aaa7b9}.mission-objective b{color:#e8d7a8}.objective-check{width:15px;height:15px;border-radius:50%;background:#81d6b31a;color:#8be0bc;display:grid;place-items:center;font-size:9px}.intel-panel{border:1px solid var(--line);border-radius:10px;background:#1a1b2b;padding:14px 15px 11px}.intel-heading{margin-bottom:9px;align-items:center}.intel-heading h3{font:600 17px 'Space Grotesk';margin:4px 0 0}.more-btn{border:0;background:none;color:#918da5;letter-spacing:2px}.enemy-list{display:flex;flex-direction:column}.enemy-entry{height:43px;display:flex;align-items:center;gap:9px;border-bottom:1px solid #ffffff0a}.enemy-portrait{width:29px;height:29px;border-radius:8px;display:grid;place-items:center;font-size:16px}.slime{color:#86d3cb;background:#74c9bf16}.brute{color:#e4ae7e;background:#e4ae7e18}.boss{color:#e792b2;background:#e792b218}.enemy-entry b{font-size:9px;display:block}.enemy-entry small{font-size:6px;letter-spacing:.55px;color:#9290a4;display:block;margin-top:3px}.enemy-threat{margin-left:auto;font-size:6px;letter-spacing:.7px;font-weight:800;padding:4px 6px;border-radius:4px}.low-threat{color:#84d0b1;background:#84d0b112}.med-threat{color:#e8c179;background:#e8c17912}.high-threat{color:#e78da5;background:#e78da512}.intel-tip{display:flex;align-items:flex-start;gap:8px;margin-top:10px;padding:8px;border-radius:7px;background:#ffffff05}.intel-tip>span{color:var(--gold);font-size:12px}.intel-tip p{font-size:7px;line-height:1.5;color:#aaa7b9;margin:0}.intel-tip p b{font-size:6px;letter-spacing:.8px;color:#d7c892}.side-quote{padding:9px 5px 2px;display:grid;grid-template-columns:23px 1fr;align-items:start}.side-quote>span{color:var(--gold);font-size:17px}.side-quote p{margin:0;color:#a9a5ba;font:italic 11px/1.5 'Space Grotesk'}.side-quote small{grid-column:2;font-size:6px;letter-spacing:1px;color:#77758d;margin-top:4px}.bottom-bar{height:43px;border-top:1px solid var(--line);display:flex;align-items:center;justify-content:space-between;color:#77768c}.bottom-world{font-size:7px;font-weight:700;letter-spacing:1.3px}.bottom-world span{color:var(--gold);font-size:12px;margin-right:6px}.footer-links{display:flex;align-items:center;gap:13px}.footer-links button{border:0;padding:0;background:none;color:#8b899f;font-size:7px;letter-spacing:.8px}.footer-links button:hover{color:var(--cream)}.footer-links button span{color:#83d6b5;margin-left:3px}.footer-links i{height:10px;width:1px;background:#ffffff19}.build-version{font-size:7px;letter-spacing:.6px}.build-version span{padding:0 5px;color:#c5a65f}.wave-banner{transition:opacity .3s,transform .3s}.wave-banner.hide{opacity:0;transform:translateY(-8px);pointer-events:none}.battle-toast{position:absolute;z-index:8;top:50%;left:50%;transform:translate(-50%,-50%);padding:12px 20px;background:#171728df;border:1px solid #edc7735c;border-radius:9px;font:600 12px 'Space Grotesk';letter-spacing:.6px;box-shadow:0 10px 30px #0005;opacity:0;transition:opacity .2s;pointer-events:none;white-space:nowrap}.battle-toast.show{opacity:1}.toast{position:fixed;z-index:30;bottom:28px;left:50%;transform:translate(-50%,12px);background:#25243a;border:1px solid #ffffff20;border-radius:8px;padding:10px 15px;font-size:11px;color:#eee9dc;opacity:0;transition:.25s;pointer-events:none;box-shadow:0 8px 24px #0005}.toast.show{opacity:1;transform:translate(-50%,0)}.modal-backdrop{position:fixed;inset:0;background:#080912bd;z-index:20;display:none;align-items:center;justify-content:center;padding:20px;backdrop-filter:blur(8px)}.modal-backdrop.open{display:flex}.modal-card{position:relative;width:min(460px,100%);max-height:min(80vh,650px);overflow:auto;border:1px solid #c4adff35;border-radius:16px;background:radial-gradient(ellipse at 90% 0%,#3b3557,#1d1d30 48%,#191a2a);padding:28px;box-shadow:0 22px 80px #0008;animation:modalIn .22s ease-out}@keyframes modalIn{from{transform:translateY(8px);opacity:.5}to{transform:none;opacity:1}}.modal-close{position:absolute;right:16px;top:13px;border:0;background:none;color:#aaa6bd;font-size:25px}.modal-card>.eyebrow{color:#b8a2ff}.modal-card h2{font:600 26px 'Space Grotesk';margin:8px 0 17px}.modal-done{margin-top:20px;border:0;border-radius:7px;background:var(--gold);color:#29251d;padding:11px 15px;font-size:8px;letter-spacing:1px;font-weight:800}.modal-done span{margin-left:17px;font-size:13px}.deck-list{display:grid;gap:8px}.deck-option{display:flex;align-items:center;gap:11px;padding:10px;border:1px solid #ffffff12;background:#ffffff05;border-radius:9px}.deck-option.selected{border-color:#edc7736b;background:#edc7730b}.deck-option .hero-art{height:52px;width:44px;flex-basis:44px}.deck-option .hero-art .hair{transform:scale(.8);top:1px}.deck-option .hero-art:after{transform:scale(.8);top:5px}.deck-option .hero-art .eyes{transform:scale(.8);top:15px}.deck-option .hero-copy{flex:1}.deck-option .hero-copy strong{font-size:11px}.deck-option .hero-copy small{font-size:8px}.deck-option button{border:1px solid #ffffff1c;background:#ffffff08;border-radius:6px;padding:6px 9px;color:#d5c996;font-size:8px}.deck-option button:disabled{opacity:.35}.story-copy{font-size:12px;line-height:1.75;color:#c3bfd0}.story-copy b{color:#f0d48f}.story-chapters{display:grid;gap:8px;margin-top:16px}.chapter-row{display:flex;align-items:center;gap:11px;border:1px solid #ffffff12;border-radius:8px;padding:10px;color:#bdb9c9;font-size:10px}.chapter-row.active{border-color:#edc77350;background:#edc77309}.chapter-num{width:25px;height:25px;border-radius:7px;background:#ffffff0b;display:grid;place-items:center;color:var(--gold);font:600 10px 'Space Grotesk'}.chapter-row small{display:block;color:#828095;margin-top:3px;font-size:8px}.skin-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}.skin-choice{padding:10px 6px;border:1px solid #ffffff16;border-radius:9px;background:#ffffff05;text-align:center}.skin-choice.active{border-color:#edc77377}.skin-swatch{height:56px;border-radius:7px;margin-bottom:7px;background:linear-gradient(145deg,var(--swatch),#25243a);display:grid;place-items:center;font-size:24px}.skin-choice strong{font-size:9px;display:block}.skin-choice small{font-size:7px;color:#9b98ad}.codex-detail{display:flex;gap:13px;align-items:center;border-bottom:1px solid #ffffff12;padding:10px 0}.codex-detail .enemy-portrait{width:43px;height:43px;font-size:22px}.codex-detail strong{font-size:12px}.codex-detail p{margin:4px 0 0;font-size:9px;color:#a6a2b5;line-height:1.5}.victory-state{text-align:center;padding:10px}.victory-state .victory-star{font-size:50px;color:var(--gold);text-shadow:0 0 30px #edc77380}.victory-state h3{font:600 21px 'Space Grotesk';margin:6px}.victory-state p{font-size:11px;line-height:1.6;color:#aaa7ba}.defeat-state{text-align:center;padding:10px}.defeat-state>span{font-size:45px;color:#e98a9d}.defeat-state h3{font:600 21px 'Space Grotesk'}.defeat-state p{font-size:11px;line-height:1.6;color:#aaa7ba}.skin-unlock{color:#edc773}
