function sellTower(){if(!selectedTower)return;const t=selectedTower;gold+=Math.round(t.def.cost*.55);scene.remove(t.obj);towers=towers.filter(x=>x!==t);selectedTower=null;updateHud();refreshSelection();showToast(`${t.def.name} returned to formation`)}
function startWave(){if(waveActive||gameEnded||wave>=5)return;wave++;waveActive=true;phase='battle';spawnLeft=8+(wave-1)*3;updateHud();$('#bannerWave').textContent=String(wave).padStart(2,'0');$('#bannerCount').textContent=spawnLeft;$('#waveBanner').classList.remove('hide');battleToast(wave===5?'BOSS WAVE — RIFT WARDEN!':`WAVE ${String(wave).padStart(2,'0')} — HOLD THE LINE`);spawnClock=.5;}
let spawnClock=0;
function makeProjectile(t,target){const mat=new THREE.MeshBasicMaterial({color:t.def.shot});const geo=t.id==='kael'?new THREE.OctahedronGeometry(.13):t.id==='mira'?new THREE.SphereGeometry(.14,8,7):new THREE.IcosahedronGeometry(.11,0);const p=mesh(geo,mat,scene,[t.x,.95,t.z]);p.userData={target,damage:t.def.damage*(1+(t.level-1)*.55),speed:7.8,life:2,color:t.def.shot};projectiles.push(p);if(t.id==='mira'){const light=new THREE.PointLight(t.def.shot,1.6,2);p.add(light)}}
function damageEnemy(e,damage,color){if(e.dead)return;e.hp-=damage;const ratio=Math.max(0,e.hp/e.maxHp);e.fill.scale.x=ratio;e.fill.position.x=-(e.boss?1.15:.62)*(1-ratio)/2;if(e.hp<=0){e.dead=true;scene.remove(e.obj);gold+=e.reward;kills++;streak++;bestStreak=Math.max(streak,bestStreak);if(e.boss)gold+=40;burst(e.obj.position,color||'#d9b8ff');updateHud()}}
function burst(position,color){for(let i=0;i<7;i++){const m=mesh(new THREE.SphereGeometry(.045,6,5),new THREE.MeshBasicMaterial({color,transparent:true}),scene,position.toArray());particles.push({mesh:m,life:.5,v:new THREE.Vector3(THREE.MathUtils.randFloatSpread(2),THREE.MathUtils.randFloat(.6,2),THREE.MathUtils.randFloatSpread(2))})}}
function castUltimate(){if(!waveActive||!enemies.length){showToast('Wait for a wave to begin');return}const alive=enemies.filter(e=>!e.dead);if(!alive.length)return;alive.forEach(e=>{damageEnemy(e,90,'#e4d3ff');e.speed*=.42;setTimeout(()=>{if(!e.dead)e.speed/=.42},1800)});burst(new THREE.Vector3(0,1,0),'#e2cbff');battleToast('✧ STARFALL — 90 DAMAGE & SLOW ✧');$('#ultimateBtn').disabled=true;setTimeout(()=>updateHud(),900);}

