function onPointerDown(ev){if(ev.target.closest('button')||ev.target.closest('.tower-action'))return;const rect=canvas.getBoundingClientRect();pointer.x=((ev.clientX-rect.left)/rect.width)*2-1;pointer.y=-((ev.clientY-rect.top)/rect.height)*2+1;raycaster.setFromCamera(pointer,camera);const hits=raycaster.intersectObjects(scene.children,true);let towerHit=null;for(const hit of hits){let o=hit.object;while(o&&o!==scene){const found=towers.find(t=>t.obj===o);if(found){towerHit=found;break}o=o.parent}if(towerHit)break}if(towerHit){selectedTower=towerHit;selectedHero=null;refreshSelection();return}const tileHit=hits.find(h=>h.object.userData.buildTile);if(tileHit&&selectedHero){const tile=tileHit.object,pos=tile.userData.pos,h=heroes.find(x=>x.id===selectedHero);if(towers.some(t=>Math.hypot(t.x-pos.x,t.z-pos.z)<.7)){showToast('That tile is occupied');return}if(!spend(h.cost))return;createTower(h.id,pos.x,pos.z);selectedTower=towers[towers.length-1];selectedHero=null;refreshSelection();showPlacementHint('');$('#phaseText').textContent='DEFENSE POSITIONED';return}selectedTower=null;refreshSelection()}
canvas.addEventListener('pointerdown',onPointerDown);
$('#startWave').addEventListener('click',startWave);$('#ultimateBtn').addEventListener('click',castUltimate);
$('#speedButton').addEventListener('click',()=>{speed=speed===1?1.5:1;$('#speedButton').textContent=`×${speed===1?1:1.5}`;showToast(speed===1?'Battle speed ×1':'Battle speed ×1.5')});
$('#cameraButton').addEventListener('click',()=>{cameraMode=(cameraMode+1)%2;camera.position.set(cameraMode?4:0,14,cameraMode?16:15);camera.lookAt(cameraMode?1:0,0,0);showToast(cameraMode?'Camera angle changed':'Camera centered')});
$('#editDeck').addEventListener('click',()=>openModal('YOUR FORMATION','Battle Deck',deckModal()));$('#storyButton').addEventListener('click',()=>openModal('CHAPTER 01','The Moonlit Frontier',storyModal()));$('#skinsButton').addEventListener('click',()=>openModal('COSMETICS','Hero skins',skinsModal()));$('#codexButton').addEventListener('click',()=>openModal('FIELD INTEL','Enemy codex',codexModal()));
$('#soundButton').addEventListener('click',()=>{soundOn=!soundOn;$('#soundState').textContent=soundOn?'ON':'OFF';showToast(`Sound ${soundOn?'on':'off'}`)});
$('#modalClose').addEventListener('click',closeModal);$('#modalDone').addEventListener('click',closeModal);$('#modalBackdrop').addEventListener('click',e=>{if(e.target.id==='modalBackdrop')closeModal()});window.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal();if(e.key.toLowerCase()==='q')castUltimate()});
function openModal(eyebrow,title,content){$('#modalEyebrow').textContent=eyebrow;$('#modalTitle').textContent=title;$('#modalContent').innerHTML=content;$('#modalBackdrop').classList.add('open');$('#modalBackdrop').setAttribute('aria-hidden','false');$('#modalContent').querySelectorAll('[data-action]').forEach(btn=>btn.addEventListener('click',()=>{const action=btn.dataset.action;if(action==='toggle-deck')toggleDeck(btn.dataset.hero);if(action==='skin')applySkin(btn.dataset.hero,btn.dataset.skin)}))}
function closeModal(){$('#modalBackdrop').classList.remove('open');$('#modalBackdrop').setAttribute('aria-hidden','true')}
function artMarkup(h){return `<span class="hero-art" style="--hero-color:${h.color};--hair:${h.hair}"><i class="hair"></i><i class="eyes"></i><i class="spark">✦</i></span>`}
function deckModal(){return `<p class="story-copy">Choose up to <b>5 heroes</b> for your field formation. A good deck balances range, power, and attack speed.</p><div class="deck-list">${heroes.map(h=>`<div class="deck-option ${activeDeck.includes(h.id)?'selected':''}">${artMarkup(h)}<span class="hero-copy"><strong>${h.name} · ${h.role}</strong><small>${h.element} · ${h.skill} · ${h.cost} ✦</small></span><button data-action="toggle-deck" data-hero="${h.id}">${activeDeck.includes(h.id)?'REMOVE':'ADD'}</button></div>`).join('')}</div>`}
function toggleDeck(id){const index=activeDeck.indexOf(id);if(index>=0){if(activeDeck.length<=1){showToast('Your deck needs at least one hero');return}activeDeck.splice(index,1);if(selectedHero===id)selectedHero=null}else if(activeDeck.length<5)activeDeck.push(id);else{showToast('Your deck is full');return}openModal('YOUR FORMATION','Battle Deck',deckModal());updateHud()}
function storyModal(){return `<p class="story-copy">Beyond the old star roads, the <b>Moonlit Frontier</b> is unraveling. A rift has cracked the ice beneath the pass, and the Voidlings have begun to pour through. Lyra's beacon is the last light for miles. Hold the ridge until reinforcements arrive at dawn.</p><div class="story-chapters"><div class="chapter-row active"><span class="chapter-num">01</span><span><b>Moonlit Pass</b><small>Frostfall Ridge · 5 waves · In progress</small></span></div><div class="chapter-row"><span class="chapter-num">02</span><span><b>Glasswood Crossing</b><small>Verdant Expanse · Locked</small></span></div><div class="chapter-row"><span class="chapter-num">03</span><span><b>The Sunken Observatory</b><small>Azure Reach · Locked</small></span></div></div>`}
function skinsModal(){const h=heroes.find(x=>x.id==='lyra');return `<p class="story-copy">Dress your heroes for the frontier. Select a skin to change the party's battlefield palette.</p><div class="skin-grid"><button class="skin-choice active" data-action="skin" data-hero="all" data-skin="Moonlit"><span class="skin-swatch" style="--swatch:#8a79c8">✧</span><strong>Moonlit</strong><small>OWNED</small></button><button class="skin-choice" data-action="skin" data-hero="all" data-skin="Dawnfire"><span class="skin-swatch" style="--swatch:#d17954">☼</span><strong>Dawnfire</strong><small>2,400 ✦</small></button><button class="skin-choice" data-action="skin" data-hero="all" data-skin="Starlight"><span class="skin-swatch" style="--swatch:#b3c5d4">✦</span><strong>Starlight</strong><small>CHAPTER 02</small></button></div>`}
function applySkin(id,skin){if(skin!=='Moonlit'){showToast('New skins unlock as your story unfolds ✦');return}heroes.forEach(h=>h.skin=skin);closeModal();showToast(`${skin} palette equipped`)}
function codexModal(){return `<p class="story-copy">Rift creatures grow stronger with every wave. Watch their approach and adapt your formation.</p><div class="codex-detail"><span class="enemy-portrait slime">◉</span><span><strong>Voidling · Swift</strong><p>A fragile scout that slips through gaps. Keep wide coverage near the first bend.</p></span></div><div class="codex-detail"><span class="enemy-portrait brute">◆</span><span><strong>Ironhide · Armored</strong><p>Heavy shell resists the cold. Focus fire from multiple heroes.</p></span></div><div class="codex-detail"><span class="enemy-portrait boss">♜</span><span><strong>Rift Warden · Boss</strong><p>Enters during the final wave. Defeating it grants a Starshard bounty.</p></span></div>`}

let last=performance.now(), uiClock=0;
function update(dt){if(waveActive){elapsed+=dt;spawnClock-=dt;if(spawnLeft>0&&spawnClock<=0){const count=8+(wave-1)*3,index=count-spawnLeft;const boss=wave===5&&index===count-1,armored=!boss&&(wave>=2&&index%4===3);createEnemy(boss,armored);spawnLeft--;$('#bannerCount').textContent=spawnLeft;spawnClock=Math.max(.47,1.08-wave*.08)+(Math.random()*.24)}
 for(const e of enemies){if(e.dead)continue;e.t+=e.speed*dt/pathLength;const p=route.getPointAt(Math.min(e.t,1));e.obj.position.set(p.x,.02+Math.sin(elapsed*5+e.t*30)*.055,p.z);e.obj.rotation.y=Math.sin(elapsed*2+e.t*11)*.12;e.bar.lookAt(camera.position);if(e.t>=.999){e.dead=true;scene.remove(e.obj);lives=Math.max(0,lives-e.damage);streak=0;updateHud();if(lives===0)endMission(false)}}
 for(const t of towers){t.cool-=dt;let target=null,best=-1;for(const e of enemies){if(e.dead)continue;const d=Math.hypot(e.obj.position.x-t.x,e.obj.position.z-t.z);if(d<=t.def.range+(t.level-1)*.25&&e.t>best){best=e.t;target=e}}if(target&&t.cool<=0){makeProjectile(t,target);t.cool=t.def.rate/(1+(t.level-1)*.15)}}
 for(let i=projectiles.length-1;i>=0;i--){const p=projectiles[i],target=p.userData.target;if(!target||target.dead){scene.remove(p);projectiles.splice(i,1);continue}const destination=target.obj.position.clone();destination.y+=.55;const delta=destination.sub(p.position),dist=delta.length(),step=p.userData.speed*dt;if(dist<step+.12){damageEnemy(target,p.userData.damage,p.userData.color);burst(p.position,p.userData.color);scene.remove(p);projectiles.splice(i,1)}else{p.position.addScaledVector(delta.normalize(),step);p.rotation.x+=dt*7;p.rotation.y+=dt*8}}
 if(spawnLeft===0&&enemies.every(e=>e.dead)){waveActive=false;phase='cleared';streak=0;gold+=35+wave*5;$('#waveBanner').classList.add('hide');if(wave>=5)endMission(true);else battleToast(`WAVE ${String(wave).padStart(2,'0')} CLEARED · +${35+wave*5} ✦`);updateHud()}}
 for(const t of towers){t.obj.userData.anim+=dt*3;t.obj.position.y=.04+Math.sin(t.obj.userData.anim)*.035;t.obj.rotation.y=Math.sin(t.obj.userData.anim*.4)*.06}
 for(let i=particles.length-1;i>=0;i--){const p=particles[i];p.life-=dt;p.mesh.position.addScaledVector(p.v,dt);p.v.y-=dt*2;p.mesh.material.opacity=Math.max(0,p.life*2);if(p.life<=0){scene.remove(p.mesh);particles.splice(i,1)}}
 uiClock+=dt;if(uiClock>.25){uiClock=0;if(!waveActive)$('#timerValue').textContent=`${String(Math.floor(elapsed/60)).padStart(2,'0')}:${String(Math.floor(elapsed%60)).padStart(2,'0')}`;else $('#timerValue').textContent=`${String(Math.floor(elapsed/60)).padStart(2,'0')}:${String(Math.floor(elapsed%60)).padStart(2,'0')}`}}
function endMission(won){if(gameEnded)return;gameEnded=true;waveActive=false;phase=won?'victory':'defeat';updateHud();if(won){$('#objectiveCheck').textContent='✓';setTimeout(()=>openModal('MISSION COMPLETE','The dawn is yours',`<div class="victory-state"><div class="victory-star">✦</div><h3>Moonlit Pass defended!</h3><p>The Rift Warden has fallen. Dawn breaks over Frostfall Ridge.<br><br><span class="skin-unlock">✦ +${gold} Starshards earned · Chapter 02 unlocked</span></p></div>`),650)}else setTimeout(()=>openModal('KEEP BREACHED','Regroup, Starkeepers',`<div class="defeat-state"><span>☾</span><h3>The rift overwhelms the ridge</h3><p>Your heroes fought bravely. Strengthen your formation and try the pass again.</p></div>`),650)}
function animate(now){requestAnimationFrame(animate);const dt=Math.min(.05,(now-last)/1000)*speed;last=now;update(dt);renderer.render(scene,camera)}requestAnimationFrame(animate);
updateHud();

